  `cancel_status` tinyint NOT NULL DEFAULT '0' COMMENT '取消状态: 0正常 1已取消',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order` (`order_id`) USING BTREE,
  KEY `idx_product` (`product_id`) USING BTREE
