INSERT INTO `review` VALUES (8001,9001,7001,2,1007,102,5,'我家金毛特别爱吃这款狗粮，颗粒大小合适，吃完便便也很正常！下次还会回购的。','[\"https://images.unsplash.com/photo-1583337130417-3346a1be7dee?auto=format&fit=crop&w=400&q=80\"]','谢谢您的支持！皇家品牌值得信赖，欢迎下次光临喵汪优粮馆~','2026-07-01 12:00:00','2026-07-01 12:30:00',0),(8002,9002,7002,1001,1001,101,5,'非常健康活泼的小金毛，接到家第一天就很黏人，感谢萌宠之家！','[]','哈哈，金毛确实很亲人，有问题随时联系我们售后哦。','2026-07-01 13:10:00','2026-07-01 13:15:00',0),(8003,9003,7003,1002,1010,102,4,'发货很快，包装完整。猫咪比较挑食，这个罐头勉强吃了几口，不过质量看起来没问题。','[]',NULL,'2026-07-01 14:20:00','2026-07-01 14:20:00',0),(8004,9004,7004,1003,1021,104,5,'小熊玩具很有意思，狗狗一拿到就疯狂咬，声音也很响亮，很满意！','[\"https://images.unsplash.com/photo-1576201836106-db1758fd1c97?auto=format&fit=crop&w=400&q=80\"]',NULL,'2026-07-01 15:30:00','2026-07-01 15:30:00',0),(8005,9005,7005,2,1013,103,3,'飞盘材质有点硬，我家小狗咬不动，可能适合中大型犬。','[]','亲，如果是小型犬可以考虑买我们店里另一款软硅胶的飞盘哦，这款确实偏硬一点。','2026-07-01 16:40:00','2026-07-01 16:50:00',0),(2072853306660708353,2072853137395376129,2072853137395376131,2,1027,106,5,'Tetseetse','[]',NULL,'2026-07-03 09:21:55','2026-07-03 09:21:55',0),(2072950550600736770,2072950363354423298,2072950363354423300,2,1027,106,5,'非常好。。','[]',NULL,'2026-07-03 15:48:19','2026-07-03 15:48:19',0),(2074319285785743362,2074318304753561601,2074318304820670466,2,1031,105,5,'1111111111','[]',NULL,'2026-07-07 10:27:11','2026-07-07 10:27:11',0),(2074320058372345857,2074319398100815874,2074319398100815876,2,1008,102,5,'1111111111111111111111111111111','[]',NULL,'2026-07-07 10:30:16','2026-07-07 15:38:37',1),(2074330830351663106,2074330725317902337,2074330725317902339,2,1009,102,5,'1245522154521','[]',NULL,'2026-07-07 11:13:04','2026-07-07 11:13:04',0),(2074389865125937153,2072862030200659970,2072862030200659972,1,1002,101,5,'我爱玩原神','[\"http://th5y5cvlf.hd-bkt.clouddn.com/reviews/a7e97811e0654a0a936031348c00712a.png?e=1814944049&token=au9DbHeMHDmgU1zr3QJY7sh78Q0O7HEz6-j6y-4Y:5YN1LVo8rr1gu7oZhuzHP59nXiM=\"]',NULL,'2026-07-07 15:07:39','2026-07-07 15:07:39',0),(2074396649102278657,207439644407